//! 🎒️ Ticket-only actual first-party two-field PNG logical Record fixture emission.
use semio_framework_dsl_record::{FieldSpec,FieldValue,JoinMode,RecordLayout,RecordSpec,RecordValue,Shape};
fn spec()->RecordSpec{RecordSpec::new_owned(None,RecordLayout::Inline,vec![FieldSpec::new(0,"schema",Shape::Text),FieldSpec::new(1,"bytes",Shape::Bytes64)])}
fn record(schema:&str,bytes:&[u8])->RecordValue{let mut record=RecordValue::default();record.fields.insert(0,FieldValue::Text(schema.into()));record.fields.insert(1,FieldValue::Bytes64(bytes.into()));record}
fn binary(body:&[u8])->Vec<u8>{let token=b"stdio.png.pack v1";let mut output=Vec::with_capacity(12+token.len()+body.len());output.extend_from_slice(&[137,83,69,77,13,10,26,10]);output.extend_from_slice(&u32::try_from(token.len()).unwrap().to_le_bytes());output.extend_from_slice(token);output.extend_from_slice(body);output}
fn body(bytes:&[u8])->&[u8]{assert!(bytes.len()>=12);assert_eq!(&bytes[..8],&[137,83,69,77,13,10,26,10]);let length=usize::try_from(u32::from_le_bytes(bytes[8..12].try_into().unwrap())).unwrap();let end=12usize.checked_add(length).filter(|end|*end<=bytes.len()).unwrap();assert_eq!(&bytes[12..end],b"stdio.png.pack v1");&bytes[end..]}
fn main(){let output=std::path::PathBuf::from(std::env::args_os().nth(1).expect("generated output directory"));std::fs::create_dir_all(&output).unwrap();let spec=spec();for(schema,bytes)in[("stdio.png",include_bytes!("demo.png").as_slice()),("",b"".as_slice()),("arbitrary 世界\0schema",&[137,80,0,255])]{let owner=record(schema,bytes);let text=semio_framework_dsl_record::print(&owner,&spec,JoinMode::Document);assert_eq!(semio_framework_dsl_record::parse_exact(&text,&spec,&Default::default()).unwrap(),owner);let payload=pack::record::encode_document(&spec,&owner,&Default::default()).unwrap();assert_eq!(pack::record::encode_document(&spec,&owner,&Default::default()).unwrap(),payload);let packed=binary(&payload);assert_eq!(pack::record::decode_document(body(&packed),&spec,&Default::default()).unwrap().0,owner);if schema=="stdio.png"{std::fs::write(output.join("🗣️.dsl.semio"),format!("semio stdio.png.dsl v1\n{}",text.trim_start())).unwrap();std::fs::write(output.join("🎒️.pack.semio"),&packed).unwrap();println!("core exact demo schema=stdio.png octets={} dsl={} pack={}",bytes.len(),text.len(),packed.len());}}}
